#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long modPow(long long base, long long exp) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    cin >> n >> m >> k;

    if (k > n - 1) {
        cout << 0 << '\n';
        return 0;
    }

    vector<long long> fact(n + 1), invFact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i)
        fact[i] = fact[i - 1] * i % MOD;

    invFact[n] = modPow(fact[n], MOD - 2);
    for (int i = n; i > 0; --i)
        invFact[i - 1] = invFact[i] * i % MOD;

    long long combination =
        fact[n - 1] * invFact[k] % MOD * invFact[n - 1 - k] % MOD;

    long long answer = combination * m % MOD * modPow(m - 1, k) % MOD;
    cout << answer << '\n';

    return 0;
}

