#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
const int64 MOD = 998244353;

int64 mod_pow(int64 a, int64 e) {
    a %= MOD;
    if (a < 0) a += MOD;
    int64 result = 1;
    while (e > 0) {
        if (e & 1) result = result * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return result;
}

int64 comb(int64 n, int64 k) {
    if (k < 0 || k > n) return 0;
    k = min(k, n - k);

    int64 numerator = 1, denominator = 1;
    for (int64 i = 1; i <= k; ++i) {
        numerator = numerator * ((n - k + i) % MOD) % MOD;
        denominator = denominator * (i % MOD) % MOD;
    }

    return numerator * mod_pow(denominator, MOD - 2) % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, m, k;
    cin >> n >> m >> k;

    int64 answer = comb(n - 1, k);
    answer = answer * (m % MOD) % MOD;
    answer = answer * mod_pow(m - 1, k) % MOD;

    cout << answer << '\n';
    return 0;
}

